    private TextView activeNav(){TextView b=navByPage.get(tab);return b!=null?b:navByPage.get("library");}
    private boolean restoreFocus(String key){View v=focusViews.get(key);return v!=null&&v.isShown()&&v.requestFocus();}
    private void focusContent(){if(!restoreFocus(lastContent)){if("home".equals(tab)&&heroPlay!=null){heroPlay.requestFocus();return;}for(View v:focusViews.values())if(v.isShown()&&v.isFocusable()){v.requestFocus();return;}sourceButton.requestFocus();}}
    private boolean tabActive(int i){return i==0&&"home".equals(tab)||i==2&&"artist".equals(tab)||i==3&&"search".equals(tab)&&"albums".equals(searchKind)||i==4&&"queue".equals(tab)||i==5&&"related".equals(tab);}
    private TextView transport(){return "home".equals(tab)&&heroPlay!=null?heroPlay:play;}
    private void select(String page){if("mix".equals(tab)&&!"mix".equals(page)){++searchGeneration;busy=false;if(searchJob!=null)searchJob.cancel(true);}if(query!=null)queryText=query.getText().toString();if(!"settings".equals(tab))returnTab=tab;tab=page;render();focusContent();}
