    private void render(){
        if(closed)return;if(heroVisual!=null)heroVisual.close();heroVisual=null;visualStatus=null;visualArtKey="";String focused=lastContent;heroArt=null;heroSeek=null;heroTitle=null;heroArtist=null;heroSource=null;heroPlay=null;heroFavorite=null;heroElapsed=null;heroTotal=null;lyricPreview=null;heroArtKey="";lyricPreviewKey="";heroBackground=null;heroShuffle=null;heroRepeat=null;backdropKey="";content.removeAllViews();focusViews.clear();images.clear();artKey="";query=null;status=null;
        setText(sourceButton,"soundcloud".equals(sourceName)?"SoundCloud ▾":"YouTube Music ▾");sourceButton.setVisibility("settings".equals(tab)?View.GONE:View.VISIBLE);
        for(int i=0;i<navigation.size();i++){TextView b=navigation.get(i);if(b==activeNav()||b.hasFocus())b.setBackground(design.surface(b.hasFocus(),12));else b.setBackgroundColor(Color.TRANSPARENT);}
        bar.setVisibility(View.VISIBLE);if(topTabs.getParent()!=body){((ViewGroup)topTabs.getParent()).removeView(topTabs);body.addView(topTabs,1,new LinearLayout.LayoutParams(-1,dp(33)));}
        for(int i=0;i<tabs.size();i++)tabs.get(i).setBackground(design.tab(tabActive(i),tabs.get(i).hasFocus()));
        if("home".equals(tab)){home();}
        else if("search".equals(tab)){searchPage();}
        else if("favorites".equals(tab)||"library".equals(tab)){favorites();}
        else if("queue".equals(tab)){listPage(LauncherinPlayerService.tracks(this),true);}
        else if("playlists".equals(tab)){playlists();}else if("radio".equals(tab)||"explore".equals(tab)){discover();}else if("artist".equals(tab)){artistPage();}else if("related".equals(tab)||"mix".equals(tab)){listPage(results,false);if("mix".equals(tab)&&status!=null)status.setText(busy?"Buscando sugestões para este perfil…":listTitle);}else{settings();}
        refresh();content.post(images::visible);
        if(!focused.isEmpty()&&focusViews.containsKey(focused))restoreFocus(focused);
    }
