    private void search(){if(query!=null)queryText=query.getText().toString().trim();if(!"songs".equals(searchKind)){searchCatalog();return;}if(queryText.isEmpty()){if(query!=null)query.requestFocus();return;}if(queryText.length()>160){toast("Use até 160 caracteres.");return;}if(!"search".equals(tab)){tab="search";render();}final boolean autoPlay=playSearch;playSearch=false;final int request=++searchGeneration;final String text=queryText;final boolean sc="soundcloud".equals(sourceName);busy=true;if(status!=null)status.setText("Buscando músicas…");if(searchJob!=null)searchJob.cancel(true);searchWorker.getQueue().clear();if(query!=null)getSystemService(InputMethodManager.class).hideSoftInputFromWindow(query.getWindowToken(),0);
        searchJob=searchWorker.submit(()->{try{List<LauncherinTrack> found=searchSource.search(text,sc);main.post(()->{if(closed||!active||request!=searchGeneration)return;busy=false;results=found;lastInteraction=SystemClock.elapsedRealtime();if("search".equals(tab)){lastContent="";render();if(status!=null)status.setText(found.isEmpty()?"Nenhuma música encontrada. Tente outra busca.":"Resultados · "+sourceLabel());if(!found.isEmpty()){restoreFocus("track:"+found.get(0).url);if(autoPlay){LauncherinPlayerService.play(this,found,0);}}}});}catch(Exception e){main.post(()->{if(!closed&&active&&request==searchGeneration){busy=false;if(status!=null)status.setText(LauncherinMusicSource.error(e));}});}});
    }
    private String sourceLabel(){return labelSource(sourceName);}
