    private void searchCatalog(){if(queryText.trim().isEmpty()){openSearchKeyboard();return;}int request=++searchGeneration;String q=queryText,kind=searchKind;boolean sc="soundcloud".equals(sourceName);busy=true;if(status!=null)status.setText("Buscando no catálogo…");if(searchJob!=null)searchJob.cancel(true);searchWorker.getQueue().clear();searchJob=searchWorker.submit(()->{try{List<LauncherinMusicCatalog.Collection> found="artists".equals(kind)?Collections.emptyList():catalogSource.search(q,sc,"albums".equals(kind));List<LauncherinArtistPhotos.Profile> people="artists".equals(kind)?artistSource.find(q,sc):Collections.emptyList();main.post(()->{if(!active||closed||request!=searchGeneration)return;busy=false;collections=found;artistResults=people;lastContent="";render();if(status!=null)status.setText(found.isEmpty()&&people.isEmpty()?"A fonte não retornou itens para esta busca.":"albums".equals(kind)&&sc?"SoundCloud fornece coleções; a fonte não separa álbuns nesta integração.":"Resultados do catálogo · "+sourceLabel());focusContent();});}catch(Exception e){main.post(()->{if(active&&request==searchGeneration){busy=false;if(status!=null)status.setText(LauncherinMusicSource.error(e));}});}});}
    private void catalogRows(LinearLayout col){if("artists".equals(searchKind)){for(LauncherinArtistPhotos.Profile p:artistResults){TextView b=button(p.name,"artist",()->{LauncherinMusicLibrary.Artist a=new LauncherinMusicLibrary.Artist(p.name,sourceName,p.art);show(new AlertDialog.Builder(this).setTitle(p.name).setItems(new String[]{"Ouvir músicas","Favoritar artista/banda"},(d,n)->{if(n==0)browseArtist(a);else editArtist(a);}).create());});remember(b,"catalog-artist:"+p.url,true);LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(-1,dp(44));rp.bottomMargin=dp(7);col.addView(b,rp);}}else for(LauncherinMusicCatalog.Collection c:collections){LinearLayout row=line();row.setFocusable(true);row.setClickable(true);row.setPadding(dp(7),dp(5),dp(10),dp(5));ImageView art=new LauncherinMusicDesign.Image(this,false);art.setScaleType(ImageView.ScaleType.CENTER_CROP);row.addView(art,new LinearLayout.LayoutParams(dp(48),dp(48)));TextView title=label(c.name+"\n"+c.artist,13,LauncherinMusicDesign.TEXT);title.setMaxLines(2);title.setEllipsize(TextUtils.TruncateAt.END);title.setPadding(dp(10),0,0,0);row.addView(title,new LinearLayout.LayoutParams(0,-2,1));row.setOnClickListener(v->loadCollection(c));remember(row,"collection:"+c.url,true);LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(-1,dp(61));rp.bottomMargin=dp(7);col.addView(row,rp);images.bind(art,c.art,160,160,design.placeholder(c.name,false));}}
    private void loadCollection(LauncherinMusicCatalog.Collection collection){int request=++searchGeneration;busy=true;if(status!=null)status.setText("Carregando músicas…");if(searchJob!=null)searchJob.cancel(true);searchWorker.getQueue().clear();searchJob=searchWorker.submit(()->{try{List<LauncherinTrack> found=collectionSource.load(collection);main.post(()->{if(!active||closed||request!=searchGeneration)return;busy=false;results=found;searchKind="songs";queryText=collection.name;artistQuery=collection.name;lastContent="";select("search");if(found.isEmpty()&&status!=null)status.setText("A fonte não disponibilizou músicas reproduzíveis desta coleção.");});}catch(Exception e){main.post(()->{if(active&&request==searchGeneration){busy=false;if(status!=null)status.setText(LauncherinMusicSource.error(e));}});}});}
    interface RelatedSource{List<LauncherinTrack> load(LauncherinTrack seed)throws Exception;}
    RelatedSource relatedSource=LauncherinMusicSource::related;
    private void related(){LauncherinTrack t=track();if(t==null){toast("Escolha uma música primeiro.");return;}select("related");int request=++searchGeneration;busy=true;if(searchJob!=null)searchJob.cancel(true);searchJob=searchWorker.submit(()->{List<LauncherinTrack> found;try{found=relatedSource.load(t);}catch(Exception e){found=Collections.emptyList();}List<LauncherinTrack> ready=found;main.post(()->{if(!active||closed||request!=searchGeneration)return;busy=false;results=ready;render();if(ready.isEmpty())toast("A fonte não compartilhou músicas relacionadas para esta faixa.");});});}
    private void reloadVisual(){visualOptions=LauncherinVisualOptions.read(this);if(visualOptions.enabled&&visualOptions.smart&&saver!=null)stopSaver();if(heroVisual!=null){heroVisual.options(visualOptions);heroVisual.setVisibility(visualOptions.enabled?View.VISIBLE:View.GONE);heroArt.setVisibility(visualOptions.enabled?View.GONE:View.VISIBLE);}if(!visualOptions.enabled)closeVisualScreen();else if(visualScreen!=null)closeVisualScreen();if(visualStatus!=null){visualStatus.setVisibility(View.VISIBLE);if(!visualOptions.enabled)visualStatus.setText("▥  Tocando agora");}shell.setAlpha(1);}
    private void visualSettings(LinearLayout col){section(col,"Visualizador circular");visualOption(col,visualOptions.enabled?"Visualizador: ativado":"Visualizador: desativado",()->editVisual("enabled",!visualOptions.enabled));
        visualOption(col,"Proteção inteligente: "+(visualOptions.smart?"ativada":"desativada"),()->editVisual("smart",!visualOptions.smart));TextView protectionNote=label("Ativada: aplica as etapas da música. Desative para usar um dos protetores anteriores, incluindo Google Fotos, mantendo o anel na capa.",12,LauncherinMusicDesign.MUTED);col.addView(protectionNote);visualOption(col,"Permitir análise do áudio",this::requestSpectrumPermission);TextView note=label("Usa o espectro da sessão do player, não grava o microfone. O firmware pode bloquear. Ambiente não simula batidas.",12,LauncherinMusicDesign.MUTED);col.addView(note);addGap(col,6);
        visualOption(col,"Cores: "+visualOptions.palette,()->{String[] ids={"electric","cyan","violet","blue"};show(new AlertDialog.Builder(this).setTitle("Cores do visualizador").setItems(new String[]{"Azul, ciano e violeta","Ciano","Violeta","Azul"},(d,n)->editVisual("palette",ids[n])).setNegativeButton("Voltar",null).create());});
        visualOption(col,"Intensidade: "+visualOptions.intensity+"%",()->show(new AlertDialog.Builder(this).setTitle("Intensidade").setItems(new String[]{"Discreta (30%)","Equilibrada (65%)","Intensa (90%)"},(d,n)->editVisual("intensity",new int[]{30,65,90}[n])).create()));
        visualOption(col,"Movimentação: "+(visualOptions.motion?"ativada":"desativada"),()->editVisual("motion",!visualOptions.motion));visualOption(col,"Ambiente sem espectro: "+(visualOptions.ambient?"permitido":"desativado"),()->editVisual("ambient",!visualOptions.ambient));
        visualOption(col,"Proteção: "+visualOptions.dim+" / "+visualOptions.hide+" / "+visualOptions.minimal+" min",()->show(new AlertDialog.Builder(this).setTitle("Diminuir / ocultar / minimizar").setItems(new String[]{"5 / 15 / 30 minutos","10 / 20 / 45 minutos","15 / 30 / 60 minutos"},(d,n)->{try{JSONObject j=visualOptions.json();j.put("dim_minutes",new int[]{5,10,15}[n]);j.put("hide_minutes",new int[]{15,20,30}[n]);j.put("minimal_minutes",new int[]{30,45,60}[n]);LauncherinVisualOptions.save(this,new LauncherinVisualOptions(j));reloadVisual();render();}catch(Exception e){toast("Não foi possível salvar.");}}).create()));
        visualOption(col,"Na proteção: "+(visualOptions.dark?"tela preta":"visualizador"),()->editVisual("dark",!visualOptions.dark));visualOption(col,"Abrir tela preta mantendo o áudio",()->openVisualScreen(true));TextView panel=label("Tela preta não desliga a TV. Em painéis LED, a iluminação continua ligada. Não há API pública portátil para desligar só o painel.",12,LauncherinMusicDesign.MUTED);col.addView(panel);addGap(col,15);
    }
    private void visualOption(LinearLayout col,String title,Runnable action){TextView b=button(title,null,action);remember(b,"visual:"+title,true);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(39));p.bottomMargin=dp(6);col.addView(b,p);}
    private void editVisual(String key,Object value){try{JSONObject j=visualOptions.json();j.put(key,value);LauncherinVisualOptions.save(this,new LauncherinVisualOptions(j));reloadVisual();render();if("enabled".equals(key)&&visualOptions.enabled)requestSpectrumPermission();}catch(Exception e){toast("As opções anteriores foram mantidas.");}}
    private void requestSpectrumPermission(){if(checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)==android.content.pm.PackageManager.PERMISSION_GRANTED){toast("Acesso ao áudio já permitido.");return;}requestedAudio=true;requestPermissions(new String[]{android.Manifest.permission.RECORD_AUDIO},882);}
    @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] grants){super.onRequestPermissionsResult(request,permissions,grants);if(request==882){requestedAudio=false;toast(grants.length>0&&grants[0]==android.content.pm.PackageManager.PERMISSION_GRANTED?"Análise do áudio permitida.":"Sem permissão: use o modo ambiente opcional.");refresh();}}
    private void refreshVisual(LauncherinTrack t,boolean playing){long now=SystemClock.elapsedRealtime();int stage=visualOptions.enabled&&visualOptions.smart?visualOptions.stage(Math.max(0,now-lastInteraction)):0;boolean blocked=lyricsVisible||dialogOpen||busy||!hasWindowFocus()||"settings".equals(tab)||saver!=null;
        if(heroVisual!=null){heroVisual.activate(active&&visualOptions.enabled&&!blocked&&visualScreen==null);if(visualOptions.enabled){if(t!=null&&!t.url.equals(visualArtKey)){visualArtKey=t.url;images.bind(heroVisual.cover,t.art,480,480,design.placeholder(t.title,true));heroVisual.track(t.url);}heroVisual.update(LauncherinPlayerService.audioSessionId(),playing,false,stage>=1?.5f:1);setText(visualStatus,heroVisual.real()?"Espectro real do áudio":heroVisual.status()+(visualOptions.ambient?" · Ambiente sem batidas":""));}}
        if(!active||!playing){if(visualScreen!=null)closeVisualScreen();shell.setAlpha(1);return;}if(visualScreen!=null){visualScreen.update(t,LauncherinPlayerService.audioSessionId(),playing,stage,now);return;}if(visualOptions.enabled&&visualOptions.smart&&!blocked){shell.setAlpha(stage>=1?.62f:1);if(stage>=2)openVisualScreen(false);}
    }
    private void openVisualScreen(boolean black){if(visualScreen!=null)return;if(!LauncherinPlayerService.playing()){toast("Inicie uma música para usar a proteção de áudio.");return;}if(heroVisual!=null)heroVisual.activate(false);visualScreen=new LauncherinCircularScreen(this,visualOptions,images,black);shell.setVisibility(View.GONE);root.addView(visualScreen,new FrameLayout.LayoutParams(-1,-1));visualScreen.requestFocus();visualScreen.post(()->{if(visualScreen!=null)visualScreen.update(track(),LauncherinPlayerService.audioSessionId(),LauncherinPlayerService.playing(),visualOptions.stage(SystemClock.elapsedRealtime()-lastInteraction),SystemClock.elapsedRealtime());});}
    private void closeVisualScreen(){if(visualScreen==null)return;visualScreen.release();root.removeView(visualScreen);visualScreen=null;shell.setVisibility(View.VISIBLE);shell.setAlpha(1);lastInteraction=SystemClock.elapsedRealtime();transport().requestFocus();}
    private void lookupCurrentPortrait(LauncherinTrack t){if(!active||t==null||heroBackground==null||t.artist.isEmpty())return;String source="SoundCloud".equals(t.source)?"soundcloud":"youtube",key=source+":"+LauncherinArtistPhotos.normalize(t.artist);if(!t.artistArt.isEmpty()||portraitCache.containsKey(key)||photoTried.contains(key)||photoPending.size()>=2)return;for(LauncherinMusicLibrary.Artist a:library.artists())if(LauncherinArtistPhotos.normalize(a.name).equals(LauncherinArtistPhotos.normalize(t.artist)))return;photoTried.add(key);photoPending.add(key);int generation=photoGeneration;photoWorker.submit(()->{List<LauncherinArtistPhotos.Profile> found;try{found=artistSource.find(t.artist,"soundcloud".equals(source));}catch(Exception e){found=Collections.emptyList();}LauncherinArtistPhotos.Profile profile=LauncherinArtistPhotos.exact(t.artist,found);main.post(()->{if(!active||closed||generation!=photoGeneration)return;photoPending.remove(key);if(profile!=null){if(portraitCache.size()>=32)portraitCache.remove(portraitCache.keySet().iterator().next());portraitCache.put(key,profile.art);refresh();}});});}
    private void loadMissingPhotos(){if(!active||!("home".equals(tab)||"favorites".equals(tab)||"library".equals(tab)))return;LauncherinTrack track=track();for(LauncherinMusicLibrary.Artist a:library.artists())if(a.art.isEmpty()&&!photoTried.contains(a.key())&&!photoPending.contains(a.key())){View tile=focusViews.get("artist:"+a.key());boolean visible=tile!=null&&tile.isShown()&&tile.getGlobalVisibleRect(new Rect());if("home".equals(tab))visible=track!=null&&LauncherinArtistPhotos.normalize(track.artist).equals(LauncherinArtistPhotos.normalize(a.name));if(!visible)continue;if(photoPending.size()>=2)break;requestArtistPhoto(a,false);}}
    private void requestArtistPhoto(LauncherinMusicLibrary.Artist a,boolean choose){if(photoPending.contains(a.key()))return;photoPending.add(a.key());photoTried.add(a.key());int generation=photoGeneration;if(choose)toast("Buscando fotos de "+a.name+"…");photoWorker.submit(()->{List<LauncherinArtistPhotos.Profile> profiles;try{profiles=artistSource.find(a.name,"soundcloud".equals(a.source));}catch(Exception e){profiles=Collections.emptyList();}final List<LauncherinArtistPhotos.Profile> found=profiles;main.post(()->{if(closed||!active||generation!=photoGeneration)return;photoPending.remove(a.key());boolean exists=false;for(LauncherinMusicLibrary.Artist current:library.artists())if(current.key().equals(a.key())&&current.source.equals(a.source))exists=true;if(!exists)return;if(choose){if(found.isEmpty()){toast("A fonte não retornou fotos. Tente novamente depois.");return;}String[] names=new String[found.size()];for(int i=0;i<names.length;i++)names[i]=found.get(i).name;show(new AlertDialog.Builder(this).setTitle("Escolha o perfil correto").setItems(names,(d,n)->previewArtistPhoto(a,found.get(n))).setNegativeButton("Cancelar",null).create());}else{LauncherinArtistPhotos.Profile match=LauncherinArtistPhotos.exact(a.name,found);if(match!=null)saveArtistPhoto(a,match);}});});}
    private void previewArtistPhoto(LauncherinMusicLibrary.Artist artist,LauncherinArtistPhotos.Profile profile){ImageView image=new LauncherinMusicDesign.Image(this,false);image.setScaleType(ImageView.ScaleType.FIT_CENTER);LinearLayout container=column();container.setPadding(dp(20),dp(10),dp(20),dp(10));container.addView(image,new LinearLayout.LayoutParams(-1,dp(180)));TextView note=label("Confira a foto do perfil publicado pela fonte.",12,LauncherinMusicDesign.MUTED);container.addView(note);AlertDialog dialog=new AlertDialog.Builder(this).setTitle(profile.name).setView(container).setPositiveButton("Usar foto",(d,n)->saveArtistPhoto(artist,profile)).setNegativeButton("Cancelar",null).create();show(dialog);images.bind(image,profile.art,384,384,design.placeholder(profile.name,true));dialog.setOnDismissListener(d->{images.forget(image);dialogOpen=false;lastInteraction=SystemClock.elapsedRealtime();});}
    private void saveArtistPhoto(LauncherinMusicLibrary.Artist a,LauncherinArtistPhotos.Profile p){for(LauncherinMusicLibrary.Artist current:library.artists())if(current.key().equals(a.key())&&current.source.equals(a.source)){library.updateArtistArt(current,p.art);View tile=focusViews.get("artist:"+current.key());if(tile instanceof ViewGroup&&((ViewGroup)tile).getChildAt(0) instanceof ImageView)images.bind((ImageView)((ViewGroup)tile).getChildAt(0),p.art,160,160,design.placeholder(current.name,true));refresh();break;}}
    private LauncherinTrack track(){return LauncherinTrack.read(LauncherinPlayerService.snapshot(this));}
    private void command(String action){if(LauncherinPlayerService.tracks(this).isEmpty()){artistQuery="";select("search");toast("Escolha uma música para começar.");return;}LauncherinPlayerService.command(this,action);}
    private void toast(String message){Toast.makeText(this,message,Toast.LENGTH_SHORT).show();}
    private void show(AlertDialog dialog){dialogOpen=true;dialog.setOnDismissListener(d->{dialogOpen=false;lastInteraction=SystemClock.elapsedRealtime();});dialog.show();}
    static String time(long ms){long seconds=Math.max(0,ms)/1000;return seconds/60+":"+String.format(Locale.ROOT,"%02d",seconds%60);}
    @Override public void onUserInteraction(){super.onUserInteraction();lastInteraction=SystemClock.elapsedRealtime();}
    @Override public boolean dispatchKeyEvent(KeyEvent event){
        int key=event.getKeyCode();if(event.getAction()==KeyEvent.ACTION_DOWN){lastInteraction=SystemClock.elapsedRealtime();if(visualScreen!=null){closeVisualScreen();boolean pass=key==KeyEvent.KEYCODE_VOLUME_UP||key==KeyEvent.KEYCODE_VOLUME_DOWN||key==KeyEvent.KEYCODE_VOLUME_MUTE||key==KeyEvent.KEYCODE_POWER||key==KeyEvent.KEYCODE_MEDIA_PLAY_PAUSE||key==KeyEvent.KEYCODE_MEDIA_NEXT||key==KeyEvent.KEYCODE_MEDIA_PREVIOUS;if(!pass){dismissKey=key;return true;}}shell.setAlpha(1);}
        if(dismissKey==key){if(event.getAction()==KeyEvent.ACTION_UP)dismissKey=-1;return true;}
        if(saver!=null&&event.getAction()==KeyEvent.ACTION_DOWN&&(key==KeyEvent.KEYCODE_BACK||key==KeyEvent.KEYCODE_DPAD_CENTER||key==KeyEvent.KEYCODE_ENTER||key==KeyEvent.KEYCODE_DPAD_UP||key==KeyEvent.KEYCODE_DPAD_DOWN||key==KeyEvent.KEYCODE_DPAD_LEFT||key==KeyEvent.KEYCODE_DPAD_RIGHT||key==KeyEvent.KEYCODE_MENU)){dismissKey=key;stopSaver();return true;}
        if(key==KeyEvent.KEYCODE_MEDIA_PLAY_PAUSE||key==KeyEvent.KEYCODE_MEDIA_NEXT||key==KeyEvent.KEYCODE_MEDIA_PREVIOUS){if(event.getAction()==KeyEvent.ACTION_DOWN&&event.getRepeatCount()==0)command(key==KeyEvent.KEYCODE_MEDIA_NEXT?"next":key==KeyEvent.KEYCODE_MEDIA_PREVIOUS?"previous":"toggle");return true;}return super.dispatchKeyEvent(event);
    }
    @Override public void onBackPressed(){if(visualScreen!=null)closeVisualScreen();else if(saver!=null)stopSaver();else if(lyricsVisible)closeLyrics();else if(!"home".equals(tab)){artistQuery="";select("home");activeNav().requestFocus();}else super.onBackPressed();}
    @Override public void onWindowFocusChanged(boolean focus){super.onWindowFocusChanged(focus);if(focus){lastInteraction=SystemClock.elapsedRealtime();if(root!=null&&root.findFocus()==null)activeNav().requestFocus();}}
