    @Override protected void onStart(){super.onStart();active=true;photoTried.clear();reloadVisual();lastInteraction=SystemClock.elapsedRealtime();IntentFilter updates=new IntentFilter(LauncherinPlayerService.CHANGED);updates.addAction(LauncherinVisualOptions.CHANGED);if(Build.VERSION.SDK_INT>=33)registerReceiver(changed,updates,Context.RECEIVER_NOT_EXPORTED);else registerReceiver(changed,updates);images.resume();main.post(tick);}
