    @Override protected void onDestroy(){closed=true;if(heroVisual!=null)heroVisual.close();if(visualScreen!=null)visualScreen.release();photoWorker.shutdownNow();main.removeCallbacksAndMessages(null);images.close();searchWorker.shutdownNow();lyricWorker.shutdownNow();super.onDestroy();}
